function buildingSprite(b) {
  const pal = (b.town ? b.town.culture.roof : 0) % ROOFS.length;
  if (b.ruin) return ruinSprite(b.size);
  const office = b.type !== 'house' && BLD[b.type] && BLD[b.type].office && typeof officeSprite === 'function';
  if (b.type !== 'house' && b.type !== 'monument' && !office && !SPR[b.type]) return siteSprite(b.size);  // no art yet: a plain site rather than nothing
  const key = b.type === 'house' ? `h${b.tier}.${pal}.${b.var}` : b.type === 'monument' ? `m${b.era || 2}` : `${b.type}.${pal}`;
  let s = spriteCache.get(key);
  if (s) return s;
  if (b.type === 'house') s = houseSprite(b.tier, pal, b.var);
  else if (b.type === 'monument') s = monumentSprite(b.done ? (b.era || 2) : 2);
  else if (office) s = officeSprite(b.type, pal);
  else {
    const px = b.size * SPR_PX, fn = SPR[b.type];
    const extra = b.type === 'palace' ? 0 : 0;
    s = mkSprite(px, px + extra, (r, g, w, h) => fn(r, g, w, h, pal));
  }
  spriteCache.set(key, s);
  return s;
}
function ruinSprite(size) {
  const key = 'ruin' + size;
  let s = spriteCache.get(key);
  if (s) return s;
  const px = size * SPR_PX;
  s = mkSprite(px, px, r => {
    r(1, px - 5, px - 2, 4, '#7a766c');
    for (let k = 0; k < size * 5; k++) r(1 + (k * 7) % (px - 3), 3 + (k * 11) % (px - 5), 2 + k % 3, 2, k % 2 ? '#8d8a80' : '#6a665c');
    r(2, px - 9, 2, 8, '#8d8a80');
    r(px - 4, px - 7, 2, 6, '#8d8a80');
  });
  spriteCache.set(key, s);
  return s;
}
function siteSprite(size) {
  const key = 'site' + size;
  let s = spriteCache.get(key);
  if (s) return s;
  const px = size * SPR_PX;
  s = mkSprite(px, px, r => {
    r(0, 2, px, px - 2, 'rgba(120,96,64,.55)');
    for (let x = 1; x < px; x += 5) r(x, 1, 1, px - 1, '#7a5f38');
    for (let y = 3; y < px; y += 4) r(0, y, px, 1, '#8c6e42');
  });
  spriteCache.set(key, s);
  return s;
}
